 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeated palette strip: consecutive identical rows with a
    # nonzero multi-color sequence. (The strip can be horizontal or vertical.)
    best = None
    for r in range(h):
        end = r + 1
        while end < h and grid[end] == grid[r]:
            end += 1
        vals = [v for v in grid[r] if v != 0]
        if end-r >= 2 and len(vals) >= 2 and len(set(vals)) >= 2:
            if best is None or end-r > best[0]:
                best = (end-r, set(range(r, end)), vals)
    if best is not None:
        palette_rows, palette = best[1], best[2]
    else:
        # Vertical palette: repeated identical columns.
        best_col = None
        for c in range(w):
            end = c + 1
            while end < w and all(grid[r][end] == grid[r][c] for r in range(h)):
                end += 1
            vals = [grid[r][c] for r in range(h) if grid[r][c] != 0]
            if end-c >= 2 and len(vals) >= 2 and len(set(vals)) >= 2:
                if best_col is None or end-c > best_col[0]:
                    best_col = (end-c, set(range(c, end)), vals)
        if best_col is None:
            raise ValueError('palette strip not found')
        palette_cols, palette = best_col[1], best_col[2]
        palette_rows = set()

    # The motif is the non-palette color-1 shape.
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] == 1 and r not in palette_rows
           and (best is not None or c not in palette_cols)]
    if not pts:
        raise ValueError('motif not found')
    rmin, rmax = min(r for r, c in pts), max(r for r, c in pts)
    cmin, cmax = min(c for r, c in pts), max(c for r, c in pts)
    mask = {(r-rmin, c-cmin) for r, c in pts}
    mh, mw = rmax-rmin+1, cmax-cmin+1

    out = [[0 for _ in range(w)] for _ in range(h)]
    top = (h - mh*len(palette)) // 2
    for i, color in enumerate(palette):
        for dr, dc in mask:
            rr, cc = top + i*mh + dr, cmin + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
